-- Stripe is the sole billing/payment provider from this migration forward.
-- Historical migrations are intentionally retained for reproducible migration history.

delete from private.billing_provider_runtime_readiness where provider='mercado_pago';
delete from private.billing_provider_addon_price_refs where provider='mercado_pago';
delete from private.billing_provider_plan_refs where provider='mercado_pago';
delete from private.addon_checkout_attempts where provider='mercado_pago';
delete from private.billing_webhook_events where provider='mercado_pago';
delete from public.addon_subscription_payments where provider='mercado_pago';
delete from public.subscription_payments where provider='mercado_pago';
update public.store_addon_subscriptions set billing_provider='stripe' where billing_provider='mercado_pago';
update public.store_subscriptions set billing_provider='stripe' where billing_provider='mercado_pago';

drop trigger if exists trg_billing_provider_webhook_readiness on private.billing_webhook_events;
drop function if exists private.mark_billing_provider_webhook_readiness_from_event();
drop function if exists public.billing_reconcile_mercado_pago_preapproval(text,text,text,integer,text,integer,text,timestamptz);
drop function if exists public.claim_mercado_pago_webhook_event(text,text,text,jsonb);
drop function if exists public.finalize_mercado_pago_webhook_event(text,text,jsonb,text);
drop function if exists public.record_mercado_pago_webhook_event(text,text,text,jsonb);
drop function if exists public.billing_begin_addon_checkout(uuid,uuid,text,text,text);
drop function if exists public.billing_complete_addon_checkout_provider_create(uuid,uuid,text,text,text);
drop function if exists public.billing_get_addon_price_sync_context(uuid,uuid);
drop function if exists public.billing_upsert_addon_provider_price_ref(uuid,uuid,text,text,jsonb);
drop function if exists public.billing_mark_addon_provider_price_stale(uuid,text);

create or replace function private.addon_purchase_preflight_for_user(_actor_user_id uuid,_store_id uuid,_addon_code text,_billing_interval text default 'monthly') returns jsonb language plpgsql stable security definer set search_path='public','private','pg_temp' as $$
declare _addon public.addon_catalog%rowtype; _price public.addon_prices%rowtype; _store_status text; _sub public.store_addon_subscriptions%rowtype; _billing jsonb; _provider_ref private.billing_provider_addon_price_refs%rowtype; _runtime private.stripe_runtime_readiness%rowtype; _blockers jsonb:='[]'::jsonb;
begin
 if not private.is_store_manager_user(_actor_user_id,_store_id) then raise exception 'FORBIDDEN' using errcode='42501'; end if;
 if _billing_interval not in ('monthly','annual') then raise exception 'INVALID_BILLING_INTERVAL' using errcode='P0001'; end if;
 select s.status::text into _store_status from public.stores s where s.id=_store_id;
 if _store_status is null then raise exception 'STORE_NOT_FOUND' using errcode='P0001'; end if;
 select * into _addon from public.addon_catalog a where a.code=_addon_code;
 if not found then raise exception 'ADDON_NOT_FOUND' using errcode='P0001'; end if;
 select * into _price from public.addon_prices p where p.addon_id=_addon.id and p.billing_interval=_billing_interval limit 1;
 select * into _sub from public.store_addon_subscriptions s where s.store_id=_store_id and s.addon_id=_addon.id limit 1;
 _billing:=public.get_store_billing_access(_store_id);
 if _store_status<>'ativa' then _blockers:=_blockers||jsonb_build_array(jsonb_build_object('code','STORE_NOT_ACTIVE','message','A loja precisa estar ativa para contratar módulos.')); end if;
 if not _addon.is_active then _blockers:=_blockers||jsonb_build_array(jsonb_build_object('code','ADDON_INACTIVE','message','Este módulo está desativado.')); end if;
 if _addon.availability_status<>'available' then _blockers:=_blockers||jsonb_build_array(jsonb_build_object('code','ADDON_NOT_AVAILABLE','message','Este módulo ainda não está disponível para contratação.')); end if;
 if _price.id is null or not coalesce(_price.is_active,false) then _blockers:=_blockers||jsonb_build_array(jsonb_build_object('code','PRICE_NOT_PUBLISHED','message','Ainda não existe preço publicado para este período.')); elsif _price.amount_cents<=0 then _blockers:=_blockers||jsonb_build_array(jsonb_build_object('code','PRICE_NOT_CHARGEABLE','message','O preço publicado ainda não está habilitado para cobrança.')); end if;
 if coalesce(_billing->>'stage','billing_unconfigured')='billing_unconfigured' then _blockers:=_blockers||jsonb_build_array(jsonb_build_object('code','BASE_BILLING_UNCONFIGURED','message','A assinatura principal da loja precisa estar configurada antes de contratar um módulo.')); elsif not coalesce((_billing->>'can_manage_billing')::boolean,false) then _blockers:=_blockers||jsonb_build_array(jsonb_build_object('code','BILLING_RESTRICTED','message','O financeiro da loja está temporariamente bloqueado para novas contratações.')); end if;
 if _sub.id is not null then if _sub.status in ('trial','active','grace_period','complimentary') then _blockers:=_blockers||jsonb_build_array(jsonb_build_object('code','ALREADY_SUBSCRIBED','message','A loja já possui este módulo ativo.')); elsif _sub.status='pending' then _blockers:=_blockers||jsonb_build_array(jsonb_build_object('code','PURCHASE_IN_PROGRESS','message','Já existe uma contratação deste módulo em andamento.')); elsif _sub.status='past_due' then _blockers:=_blockers||jsonb_build_array(jsonb_build_object('code','ADDON_PAST_DUE','message','Regularize a cobrança anterior deste módulo antes de contratar novamente.')); end if; end if;
 if _price.id is not null then select * into _provider_ref from private.billing_provider_addon_price_refs r where r.addon_price_id=_price.id and r.provider='stripe' limit 1; if _provider_ref.id is null or coalesce(_provider_ref.provider_plan_id,'')='' then _blockers:=_blockers||jsonb_build_array(jsonb_build_object('code','PROVIDER_PRICE_NOT_MAPPED','message','A cobrança deste módulo ainda não foi sincronizada com a Stripe.')); elsif coalesce(_provider_ref.provider_status,'')<>'active' then _blockers:=_blockers||jsonb_build_array(jsonb_build_object('code','PROVIDER_PRICE_UNAVAILABLE','message','O preço deste módulo precisa ser sincronizado novamente com a Stripe.')); end if; end if;
 select * into _runtime from private.stripe_runtime_readiness where id=true;
 if _runtime.id is null then _blockers:=_blockers||jsonb_build_array(jsonb_build_object('code','PROVIDER_RUNTIME_NOT_VERIFIED','message','A Stripe ainda não concluiu a verificação operacional.')); else if not _runtime.secret_key_configured or not _runtime.publishable_key_configured or not _runtime.provider_connected then _blockers:=_blockers||jsonb_build_array(jsonb_build_object('code','PROVIDER_TOKEN_NOT_READY','message','A conexão com a Stripe precisa estar saudável antes da contratação.')); end if; if not _runtime.webhook_secret_configured then _blockers:=_blockers||jsonb_build_array(jsonb_build_object('code','PROVIDER_WEBHOOK_SECRET_NOT_READY','message','A autenticação do webhook da Stripe ainda não está configurada.')); end if; end if;
 return jsonb_build_object('ready',jsonb_array_length(_blockers)=0,'addon',jsonb_build_object('id',_addon.id,'code',_addon.code,'name',_addon.name,'availability_status',_addon.availability_status),'price',case when _price.id is null then null else jsonb_build_object('id',_price.id,'billing_interval',_price.billing_interval,'amount_cents',_price.amount_cents,'currency',_price.currency,'trial_days',_price.trial_days,'included_units',_price.included_units,'hard_limit_units',_price.hard_limit_units,'metering_metric_code',_price.metering_metric_code,'overage_unit_amount_micros',_price.overage_unit_amount_micros) end,'provider','stripe','provider_readiness',jsonb_build_object('environment',case when coalesce(_runtime.provider_connected,false) then 'production' else 'unknown' end,'connected',coalesce(_runtime.provider_connected,false),'webhook_secret_configured',coalesce(_runtime.webhook_secret_configured,false),'checked_at',_runtime.checked_at),'blockers',_blockers);
end$$;

create or replace function public.admin_list_addon_offers() returns jsonb language plpgsql stable security definer set search_path='public','private','pg_temp' as $$ declare _items jsonb; begin if not private.is_platform_admin() then raise exception 'FORBIDDEN' using errcode='42501'; end if; select coalesce(jsonb_agg(item order by (item->>'sort_order')::integer,item->>'name'),'[]'::jsonb) into _items from (select jsonb_build_object('id',a.id,'code',a.code,'name',a.name,'description',a.description,'category',a.category,'billing_model',a.billing_model,'availability_status',a.availability_status,'is_active',a.is_active,'sort_order',a.sort_order,'monthly_price',case when pm.id is null then null else jsonb_build_object('id',pm.id,'amount_cents',pm.amount_cents,'currency',pm.currency,'trial_days',pm.trial_days,'metering_metric_code',pm.metering_metric_code,'included_units',pm.included_units,'hard_limit_units',pm.hard_limit_units,'overage_unit_amount_micros',pm.overage_unit_amount_micros,'is_active',pm.is_active,'provider_ready',coalesce(rm.provider_plan_id,'')<>'' and coalesce(rm.provider_status,'active') not in ('disabled','inactive','retired'),'provider_status',rm.provider_status) end,'annual_price',case when pa.id is null then null else jsonb_build_object('id',pa.id,'amount_cents',pa.amount_cents,'currency',pa.currency,'trial_days',pa.trial_days,'metering_metric_code',pa.metering_metric_code,'included_units',pa.included_units,'hard_limit_units',pa.hard_limit_units,'overage_unit_amount_micros',pa.overage_unit_amount_micros,'is_active',pa.is_active,'provider_ready',coalesce(ra.provider_plan_id,'')<>'' and coalesce(ra.provider_status,'active') not in ('disabled','inactive','retired'),'provider_status',ra.provider_status) end,'active_subscriptions',(select count(*) from public.store_addon_subscriptions s where s.addon_id=a.id and s.status in ('trial','active','grace_period','complimentary'))) item from public.addon_catalog a left join public.addon_prices pm on pm.addon_id=a.id and pm.billing_interval='monthly' left join public.addon_prices pa on pa.addon_id=a.id and pa.billing_interval='annual' left join private.billing_provider_addon_price_refs rm on rm.addon_price_id=pm.id and rm.provider='stripe' left join private.billing_provider_addon_price_refs ra on ra.addon_price_id=pa.id and ra.provider='stripe') q; return jsonb_build_object('items',_items,'provider','stripe'); end$$;

create or replace function public.billing_begin_addon_checkout(_actor_user_id uuid,_store_id uuid,_addon_code text,_billing_interval text,_idempotency_key text,_provider text) returns jsonb language plpgsql security definer set search_path='public','private','pg_temp' as $$ declare _attempt private.addon_checkout_attempts%rowtype; _preflight jsonb; _addon_id uuid; _price_id uuid; _addon_name text; _price public.addon_prices%rowtype; _provider_ref private.billing_provider_addon_price_refs%rowtype; _subscription public.store_addon_subscriptions%rowtype; _external_reference text; begin if not private.is_store_manager_user(_actor_user_id,_store_id) then raise exception 'FORBIDDEN' using errcode='42501'; end if; if lower(btrim(coalesce(_provider,'')))<>'stripe' then raise exception 'INVALID_PROVIDER' using errcode='P0001'; end if; if _billing_interval not in ('monthly','annual') then raise exception 'INVALID_BILLING_INTERVAL' using errcode='P0001'; end if; if nullif(btrim(_idempotency_key),'') is null or length(btrim(_idempotency_key)) not between 8 and 160 then raise exception 'INVALID_IDEMPOTENCY_KEY' using errcode='P0001'; end if; select * into _attempt from private.addon_checkout_attempts a where a.store_id=_store_id and a.idempotency_key=btrim(_idempotency_key) limit 1; if found then if _attempt.provider is distinct from 'stripe' then raise exception 'IDEMPOTENCY_PROVIDER_CONFLICT' using errcode='P0001'; end if; select * into _price from public.addon_prices where id=_attempt.addon_price_id; return jsonb_build_object('reused',true,'attempt_id',_attempt.id,'attempt_status',_attempt.status,'subscription_id',_attempt.addon_subscription_id,'provider','stripe','provider_plan_id',_attempt.provider_plan_id,'provider_subscription_id',_attempt.provider_subscription_id,'provider_status',_attempt.provider_status,'checkout_url',_attempt.checkout_url,'external_reference',_attempt.external_reference,'amount_cents',_price.amount_cents,'currency',_price.currency,'trial_days',_price.trial_days,'billing_interval',_attempt.billing_interval,'failure_code',_attempt.failure_code); end if; perform pg_advisory_xact_lock(hashtextextended(_store_id::text||':'||coalesce(_addon_code,'')||':'||_billing_interval||':stripe',0)); _preflight:=private.addon_purchase_preflight_for_user(_actor_user_id,_store_id,_addon_code,_billing_interval); if not coalesce((_preflight->>'ready')::boolean,false) then raise exception 'ADDON_PURCHASE_NOT_READY' using errcode='P0001',detail=coalesce(_preflight->'blockers','[]'::jsonb)::text; end if; _addon_id:=(_preflight->'addon'->>'id')::uuid; _addon_name:=_preflight->'addon'->>'name'; _price_id:=(_preflight->'price'->>'id')::uuid; select * into _price from public.addon_prices where id=_price_id; select * into _provider_ref from private.billing_provider_addon_price_refs where addon_price_id=_price_id and provider='stripe' and provider_status='active'; if not found then raise exception 'PROVIDER_PRICE_NOT_READY' using errcode='P0001'; end if; select * into _subscription from public.store_addon_subscriptions where store_id=_store_id and addon_id=_addon_id for update; if found then update public.store_addon_subscriptions set addon_price_id=_price_id,status='pending',billing_interval=_billing_interval,billing_provider='stripe',provider_customer_id=null,provider_subscription_id=null,provider_item_id=null,provider_status=null,provider_synced_at=null,current_period_start=null,current_period_end=null,trial_ends_at=null,grace_until=null,cancel_at_period_end=false,complimentary_until=null,complimentary_reason=null,activated_at=null,cancelled_at=null,updated_at=now() where id=_subscription.id returning * into _subscription; else insert into public.store_addon_subscriptions(store_id,addon_id,addon_price_id,status,billing_interval,billing_provider) values(_store_id,_addon_id,_price_id,'pending',_billing_interval,'stripe') returning * into _subscription; end if; _external_reference:=private.addon_billing_external_reference(_subscription.id); insert into private.addon_checkout_attempts(store_id,addon_id,addon_price_id,addon_subscription_id,actor_user_id,billing_interval,provider,provider_plan_id,idempotency_key,external_reference,status) values(_store_id,_addon_id,_price_id,_subscription.id,_actor_user_id,_billing_interval,'stripe',_provider_ref.provider_plan_id,btrim(_idempotency_key),_external_reference,'created') returning * into _attempt; return jsonb_build_object('reused',false,'attempt_id',_attempt.id,'attempt_status',_attempt.status,'subscription_id',_subscription.id,'addon_code',_addon_code,'addon_name',_addon_name,'provider','stripe','provider_plan_id',_provider_ref.provider_plan_id,'provider_status',_provider_ref.provider_status,'provider_subscription_id',null,'checkout_url',null,'external_reference',_external_reference,'amount_cents',_price.amount_cents,'currency',_price.currency,'trial_days',_price.trial_days,'billing_interval',_billing_interval); end$$;

create or replace function public.billing_get_addon_price_sync_context(_actor_user_id uuid,_addon_price_id uuid,_provider text) returns jsonb language plpgsql stable security definer set search_path='public','private','pg_temp' as $$ declare _row record; begin if not private.is_platform_admin_user(_actor_user_id) then raise exception 'FORBIDDEN' using errcode='42501'; end if; if lower(btrim(coalesce(_provider,'')))<>'stripe' then raise exception 'INVALID_PROVIDER' using errcode='P0001'; end if; select p.id as price_id,p.billing_interval,p.amount_cents,p.currency,p.trial_days,p.is_active,a.id as addon_id,a.code as addon_code,a.name as addon_name,a.is_active as addon_active,a.availability_status,r.provider_plan_id,r.provider_status,r.metadata as provider_metadata into _row from public.addon_prices p join public.addon_catalog a on a.id=p.addon_id left join private.billing_provider_addon_price_refs r on r.addon_price_id=p.id and r.provider='stripe' where p.id=_addon_price_id; if not found then raise exception 'ADDON_PRICE_NOT_FOUND' using errcode='P0001'; end if; if not _row.is_active or _row.amount_cents<=0 then raise exception 'ADDON_PRICE_NOT_CHARGEABLE' using errcode='P0001'; end if; return jsonb_build_object('price_id',_row.price_id,'addon_id',_row.addon_id,'addon_code',_row.addon_code,'addon_name',_row.addon_name,'billing_interval',_row.billing_interval,'amount_cents',_row.amount_cents,'currency',_row.currency,'trial_days',_row.trial_days,'provider','stripe','provider_plan_id',_row.provider_plan_id,'provider_status',_row.provider_status,'provider_metadata',coalesce(_row.provider_metadata,'{}'::jsonb)); end$$;

create or replace function public.billing_upsert_addon_provider_price_ref(_actor_user_id uuid,_addon_price_id uuid,_provider text,_provider_plan_id text,_provider_status text,_metadata jsonb default '{}'::jsonb) returns jsonb language plpgsql security definer set search_path='public','private','pg_temp' as $$ declare _addon_id uuid; _after jsonb; begin if not private.is_platform_admin_user(_actor_user_id) then raise exception 'FORBIDDEN' using errcode='42501'; end if; if lower(btrim(coalesce(_provider,'')))<>'stripe' then raise exception 'INVALID_PROVIDER' using errcode='P0001'; end if; if nullif(btrim(_provider_plan_id),'') is null then raise exception 'INVALID_PROVIDER_PLAN_ID' using errcode='P0001'; end if; select addon_id into _addon_id from public.addon_prices where id=_addon_price_id; if _addon_id is null then raise exception 'ADDON_PRICE_NOT_FOUND' using errcode='P0001'; end if; insert into private.billing_provider_addon_price_refs(addon_price_id,provider,provider_plan_id,provider_status,metadata) values(_addon_price_id,'stripe',btrim(_provider_plan_id),nullif(btrim(coalesce(_provider_status,'')),''),coalesce(_metadata,'{}'::jsonb)) on conflict(addon_price_id,provider) do update set provider_plan_id=excluded.provider_plan_id,provider_status=excluded.provider_status,metadata=excluded.metadata,updated_at=now() returning jsonb_build_object('addon_price_id',addon_price_id,'provider',provider,'provider_plan_id',provider_plan_id,'provider_status',provider_status,'metadata',metadata,'updated_at',updated_at) into _after; insert into private.platform_addon_pricing_audit(actor_user_id,addon_id,addon_price_id,action,before_state,after_state) values(_actor_user_id,_addon_id,_addon_price_id,'provider_sync',null,_after); return _after; end$$;

create or replace function public.billing_complete_addon_checkout_provider_create(_actor_user_id uuid,_attempt_id uuid,_provider text,_provider_subscription_id text,_provider_status text,_checkout_url text) returns jsonb language plpgsql security definer set search_path='public','private','pg_temp' as $$ declare _attempt private.addon_checkout_attempts%rowtype; begin select * into _attempt from private.addon_checkout_attempts where id=_attempt_id for update; if not found then raise exception 'CHECKOUT_ATTEMPT_NOT_FOUND' using errcode='P0001'; end if; if not private.is_store_manager_user(_actor_user_id,_attempt.store_id) then raise exception 'FORBIDDEN' using errcode='42501'; end if; if lower(btrim(coalesce(_provider,'')))<>'stripe' or _attempt.provider<>'stripe' then raise exception 'PROVIDER_MISMATCH' using errcode='P0001'; end if; if nullif(btrim(_provider_subscription_id),'') is null or nullif(btrim(_checkout_url),'') is null then raise exception 'INVALID_PROVIDER_CHECKOUT' using errcode='P0001'; end if; perform private.attach_addon_provider_subscription(_attempt.addon_subscription_id,'stripe',btrim(_provider_subscription_id),null,_provider_status); update private.addon_checkout_attempts set provider_subscription_id=btrim(_provider_subscription_id),provider_status=nullif(btrim(coalesce(_provider_status,'')),''),checkout_url=btrim(_checkout_url),status='checkout_ready',failure_code=null,last_error=null,updated_at=now() where id=_attempt.id returning * into _attempt; return jsonb_build_object('attempt_id',_attempt.id,'attempt_status',_attempt.status,'subscription_id',_attempt.addon_subscription_id,'provider','stripe','provider_subscription_id',_attempt.provider_subscription_id,'provider_status',_attempt.provider_status,'checkout_url',_attempt.checkout_url,'external_reference',_attempt.external_reference); end$$;
